//! Original system-pool structs with persistent actual node-member maps.
use super::*;
use super::original_rows::{OriginalProjectionRowsDataV1,OriginalProjectionRowDataV1};
use oasis7_world_state::incremental_reward_budget_records::{RewardColumnV1 as Column,RewardCollectionV1 as Collection};
use std::{cell::RefCell,sync::Arc,mem::size_of};
use serde::Serialize;
pub(super) struct OriginalRewardPoolRecordDataV1{scalars:[Option<u64>;3],members:[Arc<OriginalProjectionRowsDataV1>;2],_fee:MemoryReservation}
fn reserve(common:&mut FormalBoundedContextV1<'_>,n:usize)->Result<MemoryReservation,BodyMutationError>{common.charge(1,n as u64).map_err(paid)?;common.memory().reserve(n,MemoryClass::Ordinary).map_err(ValueTreeError::Memory).map_err(Into::into)}
fn scalar_index(column:Column)->Result<usize,BodyMutationError>{match column{Column::EpochIndex=>Ok(0),Column::TotalCreditBudget=>Ok(1),Column::RemainingCreditBudget=>Ok(2),_=>Err(invalid("reward pool scalar owner"))}}
fn map_index(collection:Collection)->usize{match collection{Collection::NodeCreditCaps=>0,Collection::NodeCreditAllocated=>1}}
#[derive(Debug)]struct CodecCause{error:serde_json::Error,_fee:MemoryReservation}
impl std::fmt::Display for CodecCause{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{self.error.fmt(f)}}impl std::error::Error for CodecCause{}
impl OriginalRewardPoolRecordDataV1{
 pub(super) fn empty_for_new_actual_entity_v1(common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{let fee=reserve(common,size_of::<Self>()+2*size_of::<usize>())?;Ok(Arc::new(Self{scalars:[None;3],members:[Arc::new(OriginalProjectionRowsDataV1::empty_data_v1(common)?),Arc::new(OriginalProjectionRowsDataV1::empty_data_v1(common)?)],_fee:fee}))}
 pub(super) fn from_original_qualified_json_v1(bytes:&[u8],common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{let phase=reserve(common,bytes.len().checked_mul(256).and_then(|n|n.checked_add(32768)).ok_or_else(||invalid("reward pool decode phase"))?)?;common.charge(bytes.len()as u64,bytes.len()as u64).map_err(paid)?;let decoded=serde_json::from_slice::<oasis7_world_state::SystemOrderPoolBudget>(bytes);common.consume_steps(0).map_err(paid)?;let value=match decoded{Ok(v)=>v,Err(error)=>return Err(paid(CodecCause{error,_fee:phase}))};let oasis7_world_state::SystemOrderPoolBudget{epoch_index,total_credit_budget,remaining_credit_budget,node_credit_caps,node_credit_allocated}=value;let fee=reserve(common,size_of::<Self>()+2*size_of::<usize>())?;let mut members=[None,None];for(index,map)in [node_credit_caps,node_credit_allocated].into_iter().enumerate(){common.consume_steps(1).map_err(paid)?;let mut rows=OriginalProjectionRowsDataV1::empty_data_v1(common)?;for(key,value)in map{common.consume_steps(1).map_err(paid)?;let semantic=super::initial::capture(common,|out|oasis7_world_state::incremental_semantic_key::write_semantic_key_v1(&key,out).map_err(paid))?;let key=super::capture_projection_json_data_v1(&key,common)?;let value=super::capture_projection_json_data_v1(&value,common)?;let row=OriginalProjectionRowDataV1::from_original_encoded_data_v1(semantic,key,value,common)?;rows=rows.with_row_data_v1(row,common)?}members[index]=Some(Arc::new(rows))}Ok(Arc::new(Self{scalars:[Some(epoch_index),Some(total_credit_budget),Some(remaining_credit_budget)],members:members.map(|v|v.expect("two fixed original maps")),_fee:fee}))}
 pub(super) fn validate(&self,common:&mut FormalBoundedContextV1<'_>)->Result<(),BodyMutationError>{common.consume_steps(1).map_err(paid)?;if !self._fee.uses_budget(common.memory()){return Err(invalid("reward pool source pool"))}Ok(())}
 pub(super) fn validate_complete_v1(&self,common:&mut FormalBoundedContextV1<'_>)->Result<(),BodyMutationError>{self.validate(common)?;common.consume_steps(3).map_err(paid)?;if self.scalars.iter().any(Option::is_none){return Err(invalid("reward pool scalar source missing"))}Ok(())}
 fn fork(&self,common:&mut FormalBoundedContextV1<'_>)->Result<Self,BodyMutationError>{self.validate(common)?;let fee=reserve(common,size_of::<Self>()+2*size_of::<usize>())?;common.consume_steps(2).map_err(paid)?;Ok(Self{scalars:self.scalars,members:self.members.clone(),_fee:fee})}
 pub(super) fn with_scalar_v1(&self,column:Column,value:u64,common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{let mut out=self.fork(common)?;out.scalars[scalar_index(column)?]=Some(value);Ok(Arc::new(out))}
 pub(super) fn with_member_v1(&self,collection:Collection,semantic:ReservedValue<Vec<u8>>,key:ReservedValue<Vec<u8>>,after:Option<ReservedValue<Vec<u8>>>,common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{let index=map_index(collection);let mut out=self.fork(common)?;let rows=match after{Some(value)=>self.members[index].with_row_data_v1(OriginalProjectionRowDataV1::from_original_encoded_data_v1(semantic,key,value,common)?,common)?,None=>self.members[index].without_row_data_v1(&semantic,common)?};out.members[index]=Arc::new(rows);Ok(Arc::new(out))}
 pub(super) fn serialization_v1<'a,'b,'c>(&'a self,common:&'a RefCell<&'b mut FormalBoundedContextV1<'c>>,first:&'a RefCell<Option<BodyMutationError>>)->PoolSerialize<'a,'b,'c>{PoolSerialize{data:self,common,first}}
}
pub(super) struct PoolSerialize<'a,'b,'c>{data:&'a OriginalRewardPoolRecordDataV1,common:&'a RefCell<&'b mut FormalBoundedContextV1<'c>>,first:&'a RefCell<Option<BodyMutationError>>}
impl Serialize for PoolSerialize<'_,'_,'_>{fn serialize<S:serde::Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{use serde::ser::Error as _;if let Err(error)=self.data.validate_complete_v1(&mut self.common.borrow_mut()){*self.first.borrow_mut()=Some(error);return Err(S::Error::custom("reward pool source context"))}let caps=self.data.members[0].original_map_serialization_v1(self.common,self.first);let allocated=self.data.members[1].original_map_serialization_v1(self.common,self.first);oasis7_world_state::SystemOrderPoolBudgetProjectionFieldsV1{epoch_index:self.data.scalars[0].expect("checked"),total_credit_budget:self.data.scalars[1].expect("checked"),remaining_credit_budget:self.data.scalars[2].expect("checked"),node_credit_caps:&caps,node_credit_allocated:&allocated}.serialize(serializer)}}
